using System;

namespace ProjectManagement.Models.Chat;

public sealed class ChatMessage
{
    public const int MaxBodyLength = 4000;

    public long Id { get; set; }

    public long ConversationId { get; set; }

    public string SenderUserId { get; set; } = string.Empty;

    /// <summary>
    /// Generated by the sending browser. Unique per sender so a retry after a dropped
    /// connection returns the stored message instead of saving a duplicate.
    /// </summary>
    public Guid ClientMessageId { get; set; }

    /// <summary>Plain text. Never rendered as HTML.</summary>
    public string Body { get; set; } = string.Empty;

    public DateTimeOffset SentUtc { get; set; }

    /// <summary>
    /// Set when the sender unsends the message (only allowed shortly after sending). The body is
    /// cleared at the same time, so the text is really gone, not just hidden.
    /// </summary>
    public DateTimeOffset? UnsentUtc { get; set; }

    /// <summary>
    /// For a group notice ("Ravi added Sita") instead of a message: one of the
    /// <see cref="ChatGroupEvent"/> kinds, with an empty body. SenderUserId is who did it.
    /// </summary>
    public string? EventKind { get; set; }

    /// <summary>The notice's subject: the added/removed user id, or the new group name.</summary>
    public string? EventData { get; set; }

    public ChatConversation? Conversation { get; set; }
}
